-- northwind.sales_orders
CREATE TABLE northwind.sales_orders (
    id uuid NOT NULL,
    order_number varchar(20) NOT NULL DEFAULT 'SO-' || lpad(nextval('northwind.sales_order_number_seq')::text, 6, '0'),
    ordered_at timestamptz(6) NOT NULL,
    status varchar(8) NOT NULL DEFAULT 'DRAFT',
    customer_po_number varchar(40) NULL,
    source varchar(20) NOT NULL DEFAULT 'portal',
    requested_delivery_on date NULL,
    promised_delivery_on date NULL,
    bill_line1 varchar(120) NOT NULL,
    bill_line2 varchar(120) NULL,
    bill_city varchar(80) NOT NULL,
    bill_region varchar(80) NULL,
    bill_postal_code varchar(20) NULL,
    bill_country_code varchar(2) NOT NULL,
    ship_line1 varchar(120) NOT NULL,
    ship_line2 varchar(120) NULL,
    ship_city varchar(80) NOT NULL,
    ship_region varchar(80) NULL,
    ship_postal_code varchar(20) NULL,
    ship_country_code varchar(2) NOT NULL,
    freight_terms varchar(3) NULL,
    subtotal_amount numeric(19,4) NOT NULL,
    subtotal_currency varchar(3) NOT NULL,
    discount_total_amount numeric(19,4) NOT NULL,
    discount_total_currency varchar(3) NOT NULL,
    tax_total_amount numeric(19,4) NOT NULL,
    tax_total_currency varchar(3) NOT NULL,
    freight_total_amount numeric(19,4) NOT NULL,
    freight_total_currency varchar(3) NOT NULL,
    grand_total_amount numeric(19,4) NOT NULL,
    grand_total_currency varchar(3) NOT NULL,
    notes text NULL,
    created_at timestamptz(6) NOT NULL,
    created_by varchar(64) NULL,
    updated_at timestamptz(6) NULL,
    updated_by varchar(64) NULL,
    deleted_at timestamptz(6) NULL,
    customer_id uuid NOT NULL,
    contact_id uuid NULL,
    cancellation_reason_id integer NULL,
    quote_id uuid NULL,
    sales_rep_id uuid NULL,
    currency_code varchar(3) NOT NULL,
    payment_term_id integer NULL,
    price_list_id uuid NULL,
    sales_channel_id uuid NULL,
    ship_from_warehouse_id uuid NULL,
    CONSTRAINT pk_sales_orders PRIMARY KEY (id),
    CONSTRAINT uq_sales_orders_order_number UNIQUE (order_number),
    CONSTRAINT fk_sales_orders_customer_id FOREIGN KEY (customer_id) REFERENCES northwind.parties (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sales_orders_contact_id FOREIGN KEY (contact_id) REFERENCES northwind.contacts (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_cancellation_reason_id FOREIGN KEY (cancellation_reason_id) REFERENCES northwind.cancellation_reasons (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_quote_id FOREIGN KEY (quote_id) REFERENCES northwind.sales_quotes (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_sales_rep_id FOREIGN KEY (sales_rep_id) REFERENCES northwind.employees (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_currency_code FOREIGN KEY (currency_code) REFERENCES northwind.currencies (code) ON DELETE RESTRICT,
    CONSTRAINT fk_sales_orders_payment_term_id FOREIGN KEY (payment_term_id) REFERENCES northwind.payment_terms (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_price_list_id FOREIGN KEY (price_list_id) REFERENCES northwind.price_lists (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_sales_channel_id FOREIGN KEY (sales_channel_id) REFERENCES northwind.sales_channels (id) ON DELETE SET NULL,
    CONSTRAINT fk_sales_orders_ship_from_warehouse_id FOREIGN KEY (ship_from_warehouse_id) REFERENCES northwind.warehouses (id) ON DELETE SET NULL
);
CREATE INDEX ix_sales_orders_ordered_at ON northwind.sales_orders (ordered_at DESC);
CREATE INDEX ix_sales_orders_customer_po_number ON northwind.sales_orders (customer_po_number);
COMMENT ON TABLE northwind.sales_orders IS 'Order number default, amount checks and the order-date index.';
COMMENT ON COLUMN northwind.sales_orders.id IS 'Surrogate key of the sales order.';
COMMENT ON COLUMN northwind.sales_orders.order_number IS 'Assigned from sales_order_number_seq when the application does not supply one.';
COMMENT ON COLUMN northwind.sales_orders.ordered_at IS 'When the order was placed.';
COMMENT ON COLUMN northwind.sales_orders.status IS 'Lifecycle state.';
COMMENT ON COLUMN northwind.sales_orders.customer_po_number IS 'Customer''s purchase order number.';
COMMENT ON COLUMN northwind.sales_orders.source IS 'Entry channel - portal, edi, phone or email.';
